d794ca64c2d037a711e106bb1ccf013e319f158c","extension":"png","mediaType":"image/png","role":"canonical_page_image","byteSize":438026,"width":581,"height":794}},{"id":"ub2-sb-unit-10-part-1","stableKey":"ultimate-b2-students-book/pages/ub2-sb-unit-10-part-1","unitNumber":10,"sectionTitle":"Unit opener","partNumber":1,"printedPages":[139],"printedLabel":"139","label":"Unit 10 · Unit opener · 139","sortOrder":901,"image":{"sha256":"a30c1e558126ef4e24c8ea34092c2a494f49fc6ed2872262568a185fca9e6f09","extension":"png","mediaType":"image/png","role":"canonical_page_image","byteSize":549201,"width":581,"height":794}},{"id":"ub2-sb-unit-10-part-2","stableKey":"ultimate-b2-students-book/pages/ub2-sb-unit-10-part-2","unitNumber":10,"sectionTitle":"Reading","partNumber":2,"printedPages":[140,141],"printedLabel":"140-141","label":"Unit 10 · Reading · 140-141","sortOrder":902,"image":{"sha256":"3ebda5d5a32bfbfe0e081b9c75f99f3038875cd1e46fb3d6c9f711ff2ee69da8","extension":"png","mediaType":"image/png","role":"canonical_page_image","byteSize":956456,"width":1142,"height":794}},{"id":"ub2-sb-unit-10-part-3","stableKey":"ultimate-b2-students-book/pages/ub2-sb-unit-10-part-3","unitNumber":10,"sectionTitle":"Vocabulary in Use","partNumber":3,"printedPages":[142,143],"printedLabel":"142-143","label":"Unit 10 · Vocabulary in Use · 142-143","sortOrder":903,"image":{"sha256":"62197f58d862f15bd9bf56dfec11139568d16548588a51b7bea7e5ae633c3c51","extension":"png","mediaType":"image/png","role":"canonical_page_image","byteSize":640540,"width":1142,"height":794}},{"id":"ub2-sb-unit-10-part-4","stableKey":"ultimate-b2-students-book/pages/ub2-sb-unit-10-part-4","unitNumber":10,"sectionTitle":"Grammar in Use","partNumber":4,"printedPages":[144,145],"printedLabel":"144-145","label":"Unit 10 · Grammar in Use · 144-145","sortOrder":904,"image":{"sha256":"8f2b3739748c73b1c64b177cdd662282ef8ebb5289d3a1735c51641870df6608","extension":"png","mediaType":"image/png","role":"canonical_page_image","byteSize":912156,"width":1142,"height":794}},{"id":"ub2-sb-unit-10-part-5","stableKey":"ultimate-b2-students-book/pages/ub2-sb-unit-10-part-5","unitNumber":10,"sectionTitle":"Listening","partNumber":5,"printedPages":[146],"printedLabel":"146","label":"Unit 10 · Listening · 146","sortOrder":905,"image":{"sha256":"4937f7404456ea5b19bec9aa8cedef8d459075e4956418d2aed588b886a8beca","extension":"png","mediaType":"image/png","role":"canonical_page_image","byteSize":411598,"width":581,"height":794}},{"id":"ub2-sb-unit-10-part-6","stableKey":"ultimate-b2-students-book/pages/ub2-sb-unit-10-part-6","unitNumber":10,"sectionTitle":"Speaking","partNumber":6,"printedPages":[147],"printedLabel":"147","label":"Unit 10 · Speaking · 147","sortOrder":906,"image":{"sha256":"daadcf19c066bd02ff7bf131bd4bcd48c50b8d003b107b7c83b9dabe8b79e89a","extension":"png","mediaType":"image/png","role":"canonical_page_image","byteSize":382972,"width":581,"height":794}},{"id":"ub2-sb-unit-10-part-7","stableKey":"ultimate-b2-students-book/pages/ub2-sb-unit-10-part-7","unitNumber":10,"sectionTitle":"Writing","partNumber":7,"printedPages":[148,149],"printedLabel":"148-149","label":"Unit 10 · Writing · 148-149","sortOrder":907,"image":{"sha256":"263c620e0e5ff100b0e8adcc4d3a98ed6315e049b40c985692d76063520380fe","extension":"png","mediaType":"image/png","role":"canonical_page_image","byteSize":822685,"width":1142,"height":794}},{"id":"ub2-sb-unit-10-part-8","stableKey":"ultimate-b2-students-book/pages/ub2-sb-unit-10-part-8","unitNumber":10,"sectionTitle":"Review","partNumber":8,"printedPages":[150],"printedLabel":"150","label":"Unit 10 · Review · 150","sortOrder":908,"image":{"sha256":"76fd14258ca6ffb07c381f89757830d0208afdce66d8b8356bc28f506b51c273","extension":"png","mediaType":"image/png","role":"canonical_page_image","byteSize":125789,"width":581,"height":794}},{"id":"ub2-sb-unit-10-part-9","stableKey":"ultimate-b2-students-book/pages/ub2-sb-unit-10-part-9","unitNumber":10,"sectionTitle":"Practice","partNumber":9,"printedPages":[151],"printedLabel":"151","label":"Unit 10 · Practice · 151","sortOrder":909,"image":{"sha256":"a97f664c519d4933ca71d08210f97c2ad6a4bcb5b6cae2d70965e5c0255cde6a","extension":"png","mediaType":"image/png","role":"canonical_page_image","byteSize":441175,"width":581,"height":794}},{"id":"ub2-sb-unit-10-part-10","stableKey":"ultimate-b2-students-book/pages/ub2-sb-unit-10-part-10","unitNumber":10,"sectionTitle":"Practice","partNumber":10,"printedPages":[152],"printedLabel":"152","label":"Unit 10 · Practice · 152","sortOrder":910,"image":{"sha256":"bc6c90b5dfa526056b710d0ae1e1b88850a2d7446058ea4fa9e2dd31bdccc533","extension":"png","mediaType":"image/png","role":"canonical_page_image","byteSize":311608,"width":581,"height":794}},{"id":"ub2-sb-unit-10-part-11","stableKey":"ultimate-b2-students-book/pages/ub2-sb-unit-10-part-11","unitNumber":10,"sectionTitle":"Progress check","partNumber":11,"printedPages":[153],"printedLabel":"153","label":"Unit 10 · Progress check · 153","sortOrder":911,"image":{"sha256":"4cdbeb821132850828464f77caed9ee1a0c4275be95ab917448c8ac483f7e7cf","extension":"png","mediaType":"image/png","role":"canonical_page_image","byteSize":375038,"width":581,"height":794}},{"id":"ub2-sb-unit-10-part-12","stableKey":"ultimate-b2-students-book/pages/ub2-sb-unit-10-part-12","unitNumber":10,"sectionTitle":"Progress check","partNumber":12,"printedPages":[154],"printedLabel":"154","label":"Unit 10 · Progress check · 154","sortOrder":912,"image":{"sha256":"d0ba34e15d9ade52e547a7b9c134aaa684e079dfc886807ccb46a6fcd4b4417f","extension":"png","mediaType":"image/png","role":"canonical_page_image","byteSize":347201,"width":581,"height":794}}]'::jsonb)
), current_units as (
  select unit.* from units unit join scope on scope.id=unit.book_component_id where unit.unit_number between 1 and 10
), authored as (
  select page.*,asset.id asset_id,asset.checksum_sha256,asset.mime_type,asset.byte_size,asset.width,asset.height,
    (page.source_metadata->>'has_image_override'='true' or page.source_metadata->>'is_override'='true' and asset.id is not null) image_override
  from book_pages page join scope on scope.id=page.book_component_id and scope.book_package_id=page.book_package_id
  left join lateral (
    select asset.* from book_assets asset where asset.page_id=page.id and asset.book_component_id=scope.id and asset.book_package_id=scope.book_package_id
      and asset.asset_role='page_image' and asset.publication_status='draft' and asset.access_level='internal' and asset.storage_profile='private'
    order by asset.updated_at desc limit 1
  ) asset on true
), projected as (
  select canonical.page || jsonb_build_object('origin','canonical','unitId',unit.id,'unitTitle',unit.title,
    'label',case when authored.source_metadata->>'has_metadata_override'='true' then authored.label else canonical.page->>'label' end,
    'printedLabel',case when authored.source_metadata->>'has_metadata_override'='true' then coalesce(authored.source_metadata->>'printed_label','') else canonical.page->>'printedLabel' end,
    'sortOrder',case when authored.source_metadata->>'has_metadata_override'='true' then authored.sort_order else (canonical.page->>'sortOrder')::int end,
    'image',case when authored.image_override then jsonb_build_object('sha256',authored.checksum_sha256,'extension',case authored.mime_type when 'image/png' then 'png' when 'image/jpeg' then 'jpg' when 'image/webp' then 'webp' end,
      'mediaType',authored.mime_type,'role','managed_page_image','byteSize',authored.byte_size,'width',authored.width,'height',authored.height) else canonical.page->'image' end) page
  from canonical join current_units unit on unit.unit_number=(canonical.page->>'unitNumber')::int
  left join authored on authored.stable_key=canonical.page->>'stableKey'
  where coalesce(authored.source_metadata->>'is_deleted','false')<>'true' and coalesce(authored.source_metadata->>'is_permanently_deleted','false')<>'true'
    and (authored.unit_id is null or authored.unit_id=unit.id)
  union all
  select jsonb_build_object('id',substring(authored.stable_key from length('ultimate-b2-students-book/pages/')+1),'stableKey',authored.stable_key,
    'origin','managed','unitId',unit.id,'unitNumber',unit.unit_number,'unitTitle',unit.title,'sectionTitle',coalesce(authored.source_metadata->>'section_title',''),
    'partNumber',null,'printedPages','[]'::jsonb,'printedLabel',coalesce(authored.source_metadata->>'printed_label',''),'label',authored.label,'sortOrder',authored.sort_order,
    'image',jsonb_build_object('sha256',authored.checksum_sha256,'extension',case authored.mime_type when 'image/png' then 'png' when 'image/jpeg' then 'jpg' when 'image/webp' then 'webp' end,
      'mediaType',authored.mime_type,'role','managed_page_image','byteSize',authored.byte_size,'width',authored.width,'height',authored.height))
  from authored join current_units unit on unit.id=authored.unit_id
  where authored.stable_key ~ '^ultimate-b2-students-book/pages/sb-page-[a-f0-9]{32}$' and authored.source_metadata->>'is_active'='true'
    and coalesce(authored.source_metadata->>'is_deleted','false')<>'true' and coalesce(authored.source_metadata->>'is_permanently_deleted','false')<>'true'
)
select jsonb_build_object('units',coalesce((select jsonb_agg(jsonb_build_object('id',id,'slug',slug,'unitNumber',unit_number,'title',title,'sortOrder',sort_order) order by sort_order,unit_number,slug) from current_units),'[]'::jsonb),
  'pages',coalesce((select jsonb_agg(page order by (page->>'unitNumber')::int,(page->>'sortOrder')::int,page->>'id') from projected),'[]'::jsonb))
$v3pages$;

create or replace function builder_students_book_v3_sources_are_current(requested_release_id uuid)
returns boolean language plpgsql volatile as $$
declare release_row book_component_releases%rowtype; expected jsonb; actual_revision bigint; actual_sha text; activity_id text; part text; page_snapshot jsonb;
begin
  select * into release_row from book_component_releases where id=requested_release_id;
  if release_row.id is null or release_row.compiler_id is distinct from 'ultimate-b2-students-book-v3' or release_row.release_schema_version is distinct from '3.0'
    or release_row.runtime_compatibility_sha256 is distinct from 'e7b80ea67f4d36cd2055a99cb1dd390c871658fd29c513b6552ef8a4bdb214e2' then return false; end if;
  page_snapshot:=builder_students_book_v3_page_snapshot(release_row.book_component_id);
  if jsonb_array_length(page_snapshot->'units')<>10 or page_snapshot->'units' is distinct from release_row.public_projection->'units'
    or page_snapshot->'pages' is distinct from release_row.public_projection->'pages' then return false; end if;
  select revision into actual_revision from builder_component_page_revisions where book_component_id=release_row.book_component_id;
  if coalesce(actual_revision,0) is distinct from (release_row.source_snapshot->'pages'->>'revision')::bigint then return false; end if;
  for expected in select value from jsonb_array_elements(jsonb_build_array(
    jsonb_build_object('type','hotspots','source',release_row.source_snapshot->'hotspots'),
    jsonb_build_object('type','teacher_ui','source',release_row.source_snapshot->'teacherUi'),
    jsonb_build_object('type','native_activity_index','source',release_row.source_snapshot->'nativeIndex'),
    jsonb_build_object('type','unit_extras','source',release_row.source_snapshot->'unitExtras')
  )) loop
    actual_revision:=null; actual_sha:=null;
    select revision,payload_sha256 into actual_revision,actual_sha from builder_component_documents
      where book_package_id=release_row.book_package_id and book_component_id=release_row.book_component_id and document_type=expected->>'type' and document_key='default';
    if coalesce(actual_revision,0) is distinct from (expected->'source'->>'revision')::bigint
      or coalesce(actual_sha,expected->'source'->>'sha256') is distinct from expected->'source'->>'sha256' then return false; end if;
  end loop;
  for activity_id in select jsonb_object_keys(release_row.source_snapshot->'nativeActivities') loop
    foreach part in array array['public','teacher'] loop
      actual_revision:=null; actual_sha:=null; expected:=release_row.source_snapshot->'nativeActivities'->activity_id->part;
      select revision,payload_sha256 into actual_revision,actual_sha from builder_component_documents
        where book_package_id=release_row.book_package_id and book_component_id=release_row.book_component_id and document_type='native_activity_'||part and document_key=activity_id;
      if actual_revision is distinct from (expected->>'revision')::bigint or actual_sha is distinct from expected->>'sha256' then return false; end if;
    end loop;
  end loop;
  return true;
exception when invalid_text_representation or numeric_value_out_of_range then return false;
end $$;

create or replace function builder_release_sources_are_current(requested_release_id uuid)
returns boolean language plpgsql volatile as $$
declare
  release_row book_component_releases%rowtype;
  activity_id text;
  expected jsonb;
  actual_revision bigint;
  actual_sha text;
begin
  select * into release_row from book_component_releases where id=requested_release_id;
  if release_row.id is null then return false; end if;
  if release_row.compiler_id='ultimate-b2-students-book-v3' then return builder_students_book_v3_sources_are_current(requested_release_id); end if;
  if not (
    (release_row.compiler_id = 'ultimate-b2-students-book-v1' and release_row.release_schema_version = '1.0')
    or (release_row.compiler_id = 'ultimate-b2-students-book-v2' and release_row.release_schema_version = '2.0')
  ) then return false; end if;

  select revision,payload_sha256 into actual_revision,actual_sha from builder_component_documents
  where book_component_id=release_row.book_component_id and document_type='hotspots' and document_key='default';
  expected:=release_row.source_snapshot->'hotspots';
  if coalesce(actual_revision,0)<>(expected->>'revision')::bigint or coalesce(actual_sha,expected->>'sha256')<>expected->>'sha256' then return false; end if;

  actual_revision:=null; actual_sha:=null;
  select revision,payload_sha256 into actual_revision,actual_sha from builder_component_documents
  where book_component_id=release_row.book_component_id and document_type='teacher_ui' and document_key='default';
  expected:=release_row.source_snapshot->'teacherUi';
  if coalesce(actual_revision,0)<>(expected->>'revision')::bigint or coalesce(actual_sha,expected->>'sha256')<>expected->>'sha256' then return false; end if;

  for activity_id in select jsonb_object_keys(release_row.source_snapshot->'openResponse') loop
    expected:=release_row.source_snapshot->'openResponse'->activity_id->'document';
    actual_revision:=null; actual_sha:=null;
    select revision,payload_sha256 into actual_revision,actual_sha from builder_component_documents
    where book_component_id=release_row.book_component_id and document_type='open_response' and document_key=activity_id;
    if coalesce(actual_revision,0)<>(expected->>'revision')::bigint or coalesce(actual_sha,expected->>'sha256')<>expected->>'sha256' then return false; end if;
    expected:=release_row.source_snapshot->'openResponse'->activity_id->'import';
    actual_revision:=null; actual_sha:=null;
    select revision,fingerprint_sha256 into actual_revision,actual_sha from builder_open_response_imports
    where book_component_id=release_row.book_component_id and activity_key=activity_id;
    if coalesce(actual_revision,0)<>(expected->>'revision')::bigint or (actual_revision is not null and actual_sha<>expected->>'sha256') then return false; end if;
  end loop;

  if release_row.compiler_id='ultimate-b2-students-book-v1' then return true; end if;

  expected:=release_row.source_snapshot->'nativeIndex';
  actual_revision:=null; actual_sha:=null;
  select revision,payload_sha256 into actual_revision,actual_sha from builder_component_documents
  where book_component_id=release_row.book_component_id and document_type='native_activity_index' and document_key='default';
  if coalesce(actual_revision,0)<>(expected->>'revision')::bigint or coalesce(actual_sha,expected->>'sha256')<>expected->>'sha256' then return false; end if;

  for activity_id in select jsonb_object_keys(release_row.source_snapshot->'nativeActivities') loop
    expected:=release_row.source_snapshot->'nativeActivities'->activity_id->'public';
    actual_revision:=null; actual_sha:=null;
    select revision,payload_sha256 into actual_revision,actual_sha from builder_component_documents
    where book_component_id=release_row.book_component_id and document_type='native_activity_public' and document_key=activity_id;
    if coalesce(actual_revision,0)<>(expected->>'revision')::bigint or coalesce(actual_sha,'')<>expected->>'sha256' then return false; end if;
    expected:=release_row.source_snapshot->'nativeActivities'->activity_id->'teacher';
    actual_revision:=null; actual_sha:=null;
    select revision,payload_sha256 into actual_revision,actual_sha from builder_component_documents
    where book_component_id=release_row.book_component_id and document_type='native_activity_teacher' and document_key=activity_id;
    if coalesce(actual_revision,0)<>(expected->>'revision')::bigint or coalesce(actual_sha,'')<>expected->>'sha256' then return false; end if;
  end loop;

  if release_row.source_snapshot ? 'unitExtras' then
    expected:=release_row.source_snapshot->'unitExtras';
    actual_revision:=null; actual_sha:=null;
    select revision,payload_sha256 into actual_revision,actual_sha from builder_component_documents
    where book_component_id=release_row.book_component_id and document_type='unit_extras' and document_key='default';
    if coalesce(actual_revision,0)<>(expected->>'revision')::bigint or coalesce(actual_sha,expected->>'sha256')<>expected->>'sha256' then return false; end if;
  end if;
  if release_row.source_snapshot ? 'activityLifecycle' then
    expected:=release_row.source_snapshot->'activityLifecycle';
    actual_revision:=null; actual_sha:=null;
    select revision,payload_sha256 into actual_revision,actual_sha from builder_component_documents
    where book_component_id=release_row.book_component_id and document_type='activity_lifecycle' and document_key='default';
    if coalesce(actual_revision,0)<>(expected->>'revision')::bigint or coalesce(actual_sha,expected->>'sha256')<>expected->>'sha256' then return false; end if;
  end if;
  return true;
end;
$$;

create or replace function create_builder_product_release(
  requested_product_release_id uuid,requested_book_slug text,requested_release_schema_version text,requested_compiler_id text,
  requested_members jsonb,requested_request_sha256 text,requested_release_note text,actor_builder_user_id uuid,requested_client_mutation_id uuid
)
returns table(outcome text,product_release_id uuid,product_release_number bigint,source_snapshot_sha256 text,release_sha256 text,members jsonb)
language plpgsql as $$
declare
  resolved_package_id uuid; replay book_product_releases%rowtype; inserted_product book_product_releases%rowtype;
  member jsonb; member_position int; component_id uuid; component_release book_component_releases%rowtype;
  next_product_number bigint; next_component_number bigint; member_hashes text[]:='{}'; component_slugs text[]:=array['ultimate-b2-students-book','ultimate-b2-workbook','ultimate-b2-grammar-book'];
  expected_compilers text[]:=array['ultimate-b2-students-book-v2','ultimate-b2-workbook-v1','ultimate-b2-grammar-book-v1'];
  expected_schemas text[]:=array['2.0','1.0','1.0']; product_source_hash text; product_hash text;
begin
  -- Expanded schema accepts old-code v2 prepares as well as explicit v3. This
  -- changes no existing family/member/head and activates no source policy.
  if requested_members->0->>'compilerId'='ultimate-b2-students-book-v3' then
    expected_compilers[1]:='ultimate-b2-students-book-v3'; expected_schemas[1]:='3.0';
  end if;
  if requested_book_slug<>'ultimate-b2' or requested_release_schema_version<>'1.0' or requested_compiler_id<>'ultimate-b2-product-v1'
    or jsonb_typeof(requested_members)<>'array' or jsonb_array_length(requested_members)<>3
    or requested_request_sha256!~'^[a-f0-9]{64}$' or length(coalesce(requested_release_note,''))>240 then
    return query select 'invalid_request',null::uuid,null::bigint,null::text,null::text,null::jsonb; return;
  end if;
  if not exists(select 1 from builder_users where id=actor_builder_user_id and status='active' and role='developer') then
    return query select 'unauthorized_actor',null::uuid,null::bigint,null::text,null::text,null::jsonb; return;
  end if;
  select id into resolved_package_id from book_packages where slug=requested_book_slug;
  if resolved_package_id is null then return query select 'product_not_found',null::uuid,null::bigint,null::text,null::text,null::jsonb; return; end if;
  perform pg_advisory_xact_lock(hashtextextended('builder-product-publication:'||resolved_package_id::text,0));
  select * into replay from book_product_releases where book_package_id=resolved_package_id and client_mutation_id=requested_client_mutation_id;
  if replay.id is not null then
    return query select case when replay.request_sha256=requested_request_sha256 then 'idempotent' else 'mutation_id_conflict' end,
      replay.id,replay.release_number,replay.source_snapshot_sha256,replay.release_sha256,
      (select jsonb_agg(jsonb_build_object('componentSlug',component.slug,'order',family_member.member_order,'status',family_member.member_status,
        'componentReleaseId',family_member.component_release_id,'compilerId',family_member.component_compiler_id,'releaseSchemaVersion',family_member.component_release_schema_version,
        'releaseSha256',family_member.component_release_sha256,'compatibility',family_member.runtime_compatibility_sha256,'memberSha256',family_member.member_sha256,
        'unavailableReason',family_member.unavailable_reason) order by family_member.member_order)
       from book_product_release_members family_member join book_components component on component.id=family_member.book_component_id where family_member.product_release_id=replay.id);
    return;
  end if;
  for member,member_position in select value,ordinality::int from jsonb_array_elements(requested_members) with ordinality loop
    if member->>'componentSlug'<>component_slugs[member_position] or member->>'compilerId'<>expected_compilers[member_position]
      or member->>'releaseSchemaVersion'<>expected_schemas[member_position] then raise exception 'product member identity is invalid'; end if;
    select id into component_id from book_components where book_package_id=resolved_package_id and slug=component_slugs[member_position];
    if component_id is null then raise exception 'product member component is unavailable'; end if;
    perform pg_advisory_xact_lock(hashtextextended('builder-publication-component:'||component_id::text,0));
  end loop;
  select coalesce(max(release_number),0)+1 into next_product_number from book_product_releases where book_package_id=resolved_package_id;
  for member,member_position in select value,ordinality::int from jsonb_array_elements(requested_members) with ordinality loop
    select id into component_id from book_components where book_package_id=resolved_package_id and slug=component_slugs[member_position];
    select coalesce(max(release_number),0)+1 into next_component_number from book_component_releases where book_component_id=component_id;
    insert into book_component_releases(id,book_package_id,book_component_id,release_number,release_schema_version,compiler_id,runtime_compatibility_sha256,
      source_snapshot,source_snapshot_sha256,public_projection,public_projection_sha256,teacher_projection,teacher_projection_sha256,asset_manifest,
      release_sha256,request_sha256,client_mutation_id,release_note,created_by_builder_user_id)
    values((member->>'releaseId')::uuid,resolved_package_id,component_id,next_component_number,member->>'releaseSchemaVersion',member->>'compilerId',member->>'compatibility',
      member->'sourceSnapshot',member->>'sourceSnapshotSha256',member->'publicProjection',member->>'publicProjectionSha256',member->'teacherProjection',member->>'teacherProjectionSha256',member->'assetManifest',
      member->>'releaseSha256',member->>'requestSha256',requested_client_mutation_id,nullif(trim(requested_release_note),''),actor_builder_user_id)
    returning * into component_release;
    member_hashes:=array_append(member_hashes,builder_product_member_sha256(member_position,component_slugs[member_position],'included',component_release.id,
      component_release.compiler_id,component_release.release_schema_version,component_release.release_sha256,component_release.runtime_compatibility_sha256,null));
  end loop;
  product_source_hash:=builder_product_source_sha256(requested_book_slug,next_product_number,component_slugs,member_hashes);
  product_hash:=builder_product_release_sha256(requested_compiler_id,requested_release_schema_version,requested_book_slug,next_product_number,product_source_hash,requested_release_note,component_slugs,member_hashes);
  insert into book_product_releases(id,book_package_id,release_number,release_schema_version,compiler_id,source_snapshot_sha256,release_sha256,request_sha256,client_mutation_id,release_note,created_by_builder_user_id)
  values(requested_product_release_id,resolved_package_id,next_product_number,requested_release_schema_version,requested_compiler_id,product_source_hash,product_hash,requested_request_sha256,requested_client_mutation_id,nullif(trim(requested_release_note),''),actor_builder_user_id)
  returning * into inserted_product;
  for member,member_position in select value,ordinality::int from jsonb_array_elements(requested_members) with ordinality loop
    insert into book_product_release_members(product_release_id,book_package_id,book_component_id,member_order,member_status,component_release_id,component_compiler_id,
      component_release_schema_version,component_release_sha256,runtime_compatibility_sha256,member_sha256)
    select inserted_product.id,resolved_package_id,component.id,member_position,'included',release.id,release.compiler_id,release.release_schema_version,
      release.release_sha256,release.runtime_compatibility_sha256,member_hashes[member_position]
    from book_components component join book_component_releases release on release.book_component_id=component.id
    where component.book_package_id=resolved_package_id and component.slug=component_slugs[member_position] and release.id=(member->>'releaseId')::uuid;
  end loop;
  insert into builder_audit_log(builder_user_id,action,target_type,target_id,metadata) values(actor_builder_user_id,'product_preview_release_created','book_product_release',inserted_product.id::text,
    jsonb_build_object('book_slug',requested_book_slug,'release_number',inserted_product.release_number,'release_sha256',inserted_product.release_sha256,'components',component_slugs));
  return query select 'created',inserted_product.id,inserted_product.release_number,inserted_product.source_snapshot_sha256,inserted_product.release_sha256,
    (select jsonb_agg(jsonb_build_object('componentSlug',component.slug,'order',family_member.member_order,'status',family_member.member_status,
      'componentReleaseId',family_member.component_release_id,'compilerId',family_member.component_compiler_id,'releaseSchemaVersion',family_member.component_release_schema_version,
      'releaseSha256',family_member.component_release_sha256,'compatibility',family_member.runtime_compatibility_sha256,'memberSha256',family_member.member_sha256,
      'unavailableReason',family_member.unavailable_reason) order by family_member.member_order)
     from book_product_release_members family_member join book_components component on component.id=family_member.book_component_id where family_member.product_release_id=inserted_product.id);
end;
$$;

-- Publication, rather than code/schema installation or drafts, is the switch.
-- Historical rows are never updated or rejected by these INSERT-only guards.
create or replace function builder_current_legacy_activity_allowed(requested_component_id uuid)
returns boolean language sql stable as $policy$
  select not exists(
    select 1 from book_components component join book_packages package on package.id=component.book_package_id
    join book_component_releases release on release.book_component_id=component.id and release.book_package_id=package.id
    join book_component_publication_events event on event.release_id=release.id and event.book_component_id=component.id
    where component.id=requested_component_id and package.slug='ultimate-b2' and component.slug='ultimate-b2-students-book'
      and release.compiler_id='ultimate-b2-students-book-v3' and release.release_schema_version='3.0'
      and release.runtime_compatibility_sha256='e7b80ea67f4d36cd2055a99cb1dd390c871658fd29c513b6552ef8a4bdb214e2'
  )
$policy$;

create or replace function reject_new_students_book_legacy_target()
returns trigger language plpgsql as $$
declare component_id uuid;
begin
  if new.target_kind='legacy_activity' and new.activity_id is not null then
    select unit.book_component_id into component_id from activities activity join lessons lesson on lesson.id=activity.lesson_id join units unit on unit.id=lesson.unit_id where activity.id=new.activity_id;
    if component_id is not null and not builder_current_legacy_activity_allowed(component_id) then
      raise exception using errcode='PZ004',message='students_book_native_publication_required';
    end if;
  end if;
  return new;
end $$;
create trigger students_book_new_assignment_source_policy before insert on activity_assignments for each row execute function reject_new_students_book_legacy_target();
create trigger students_book_new_homework_item_source_policy before insert on homework_items for each row execute function reject_new_students_book_legacy_target();
